INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 0 FROM countries WHERE code = 'LV';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Standard & format', '[["Semantic standard", "EN 16931 -- implemented as LVS EN 16931-1:2017 and LVS CEN/TS 16931-2:2017"], ["Machine-readable syntaxes", "UBL 2.1 and Peppol BIS Billing 3.0"], ["B2G transport", "Peppol Access Points, standard practice"], ["Future B2B transport (from 2028)", "No single mandated network -- eAddress, a certified Peppol Access Point, or direct bilateral exchange, each paired with a separate VID data-reporting duty"]]', 'Latvia''s upcoming B2B regime is best understood as a decentralized e-reporting model, not a pure Peppol mandate -- Peppol is one permitted transport, not the required one.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 1 FROM countries WHERE code = 'LV';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Reporting channels to VID', '[["eAddress (e-adrese)", "Free national platform, operated by the State Digital Development Agency (VDAA), auto-forwards data to VID"], ["Certified Peppol Access Points", "Integrated with a VID API"], ["Direct exchange + manual reporting", "Bilateral EDI/email/software exchange allowed, but invoice data must separately be reported to VID (via eAddress, an operator API, or VID''s EDS) within 5 working days"]]', 'Cabinet Regulation No. 749 (adopted 9 Dec 2025, effective 1 Jan 2026) sets these procedures in detail -- its full text could not be independently verified via likumi.lv in this research session, so treat the specifics as a secondary summary pending direct confirmation.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 0 FROM countries WHERE code = 'LV';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Who''s covered, and when', '[["B2G/G2G/G2B (live)", "All Latvian-registered companies supplying budget/government institutions"], ["B2B (from 1 Jan 2028)", "All companies and taxable persons registered in Latvia, domestic transactions only -- cross-border B2B not covered"], ["Size threshold", "None confirmed -- the phased timeline gives smaller businesses more preparation time rather than a permanent exemption"], ["Exemptions", "Cash-register/fiscal-receipt transactions, National Health Service transactions, and certain national-security agencies (State Security Service, Police, Tax Police, KNAB)"]]', NULL, NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 1 FROM countries WHERE code = 'LV';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'The 2025 postponement', '[["Original plan", "Mandatory B2B e-invoicing from 1 January 2026"], ["5 June 2025", "Saeima adopts amendment postponing B2B to 1 January 2028, rejecting a rival 2027 proposal"], ["Rationale", "More preparation time for taxpayers, especially small businesses, and time to upgrade the eAddress platform"], ["30 March 2026", "Voluntary B2B phase opens as an interim step"]]', 'The European Commission''s own Latvia eInvoicing country factsheet still shows a 1 January 2026 B2B date as of this research -- it has not been updated since the postponement. Treat the more recent, independently corroborated sources on this page (including a 22 July 2026 update) as authoritative over that factsheet for the B2B date.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 0 FROM countries WHERE code = 'LV';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '⚠️ No dedicated e-invoicing penalty yet published', NULL, NULL, 'No e-invoicing-specific fine schedule has been published in Latvia as of this research -- this was stated explicitly by multiple sources, not merely absent from what we found. The practical B2G consequence today is that a non-compliant e-invoice is simply rejected by the receiving government entity, blocking payment, rather than triggering a monetary fine.');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 1 FROM countries WHERE code = 'LV';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '🧾 General accounting-law penalty framework (context only)', NULL, NULL, 'The Accounting Law''s general penalty framework (added 17 Oct 2019, in force 1 Jul 2020, penalty unit = EUR 5) sets: up to 400 units (EUR 2,000) for improper record-keeping or non-submission of reports; up to 400 units (EUR 2,000) for excise-goods documentation violations; up to 86 units (EUR 430) for other documentation/formatting violations; up to 70 units (EUR 350) for cash-operation recording violations. This predates the e-invoicing mandate and is a general bookkeeping framework likely to apply by analogy -- not a confirmed, dedicated e-invoicing fine.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 0 FROM countries WHERE code = 'LV';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Confirm you already issue structured e-invoices to Latvian government/budget entities', 'Mandatory since 1 January 2025 -- confirm your invoices are EN 16931-compliant (UBL 2.1 or Peppol BIS Billing 3.0), not paper or plain PDF.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 1 FROM countries WHERE code = 'LV';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Confirm how your e-invoice data reaches VID', 'Mandatory since 1 January 2026 for B2G/G2G/G2B transactions -- via eAddress, a certified Peppol Access Point, or manual submission through VID''s Electronic Declaration System (EDS).');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 2 FROM countries WHERE code = 'LV';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Consider opting into the voluntary B2B phase now, ahead of the 2028 deadline', 'Open since 30 March 2026 via eAddress -- using it now lets you test your reporting process well before the mandatory 1 January 2028 date.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 3 FROM countries WHERE code = 'LV';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Do not rely on the EU Commission''s Latvia eInvoicing country factsheet for the B2B date', 'It has not been updated since the 5 June 2025 postponement and still shows 1 January 2026 -- use the sources listed on this page instead.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 4 FROM countries WHERE code = 'LV';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Test your chosen B2B reporting channel well ahead of 1 January 2028', 'There is currently no confirmed grace period beyond that date, and the deadline has already been pushed back once -- don''t assume a further delay.');
